/**
 * Supplier / vendor.
 *
 * `code` is generated by supplierService (SUP-0001) and is unique among live
 * rows. Payable balance is not stored here: it is derived from the supplier's
 * opening balance plus live purchases minus payments so it can never drift.
 */
'use strict';

const mongoose = require('mongoose');
const softDeletePlugin = require('./plugins/softDelete');

const supplierSchema = new mongoose.Schema(
  {
    code: {
      type: String,
      required: [true, 'Supplier code is required'],
      trim: true,
      uppercase: true,
      maxlength: [20, 'Supplier code cannot exceed 20 characters'],
    },
    name: {
      type: String,
      required: [true, 'Supplier name is required'],
      trim: true,
      maxlength: [150, 'Supplier name cannot exceed 150 characters'],
    },
    company: {
      type: String,
      trim: true,
      default: '',
      maxlength: [150, 'Company cannot exceed 150 characters'],
    },
    contactName: {
      type: String,
      trim: true,
      default: '',
      maxlength: [120, 'Contact person cannot exceed 120 characters'],
    },
    phone: {
      type: String,
      trim: true,
      default: '',
      maxlength: [20, 'Phone cannot exceed 20 characters'],
      validate: {
        validator: (value) => !value || /^[0-9+\-()\s]{7,20}$/.test(value),
        message: 'Enter a valid phone number',
      },
    },
    whatsapp: {
      type: String,
      trim: true,
      default: '',
      maxlength: [20, 'WhatsApp number cannot exceed 20 characters'],
      validate: {
        validator: (value) => !value || /^[0-9+\-()\s]{7,20}$/.test(value),
        message: 'Enter a valid WhatsApp number',
      },
    },
    email: {
      type: String,
      trim: true,
      lowercase: true,
      default: '',
      maxlength: [190, 'Email cannot exceed 190 characters'],
    },
    address: {
      type: String,
      trim: true,
      default: '',
      maxlength: [250, 'Address cannot exceed 250 characters'],
    },
    city: {
      type: String,
      trim: true,
      default: '',
      maxlength: [80, 'City cannot exceed 80 characters'],
    },
    ntn: {
      type: String,
      trim: true,
      default: '',
      maxlength: [30, 'NTN cannot exceed 30 characters'],
    },
    paymentTermsDays: {
      type: Number,
      default: 0,
      min: [0, 'Payment terms cannot be negative'],
      max: [365, 'Payment terms cannot exceed 365 days'],
    },
    openingBalancePaisa: {
      type: Number,
      default: 0,
      min: [0, 'Opening balance cannot be negative'],
    },
    notes: {
      type: String,
      trim: true,
      default: '',
      maxlength: [1000, 'Notes cannot exceed 1000 characters'],
    },
    createdBy: { type: mongoose.Schema.Types.ObjectId, ref: 'User', default: null },
  },
  {
    timestamps: true,
    toJSON: {
      virtuals: true,
      transform(_doc, ret) {
        delete ret.__v;
        return ret;
      },
    },
    toObject: { virtuals: true },
  }
);

supplierSchema.index(
  { code: 1 },
  { unique: true, partialFilterExpression: { deletedAt: null } }
);
supplierSchema.index({ name: 1 });
supplierSchema.index({ phone: 1 });
supplierSchema.index({ city: 1 });
supplierSchema.index({ createdAt: -1 });

supplierSchema.plugin(softDeletePlugin);

module.exports = mongoose.model('Supplier', supplierSchema);
